namespace ghidra.trace.model.time.schedule;

using ghidra.pcode.emu;
using ghidra.trace.model.time.schedule.TraceSchedule;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * A step of a given thread in a schedule: repeating some number of ticks
 */
public class TickStep : AbstractStep {

	public static TickStep parse(long threadKey, string stepSpec, TimeRadix radix) {
		try {
			return new TickStep(threadKey, radix.decode(stepSpec));
		}
		catch (NumberFormatException e) {
			throw new IllegalArgumentException("Cannot parse tick step: '" + stepSpec + "'");
		}
	}

	/**
	 * Construct a tick step for the given thread with the given tick count
	 * 
	 * @param threadKey the key of the thread in the trace, -1 for the "last thread"
	 * @param tickCount the number of ticks to step on the thread
	 */
	public TickStep(long threadKey, long tickCount) : base(threadKey, tickCount)
    {
	}

	/* @Override */
	public StepType getType() {
		return StepType.TICK;
	}

	/* @Override */
	public long getSkipCount() {
		return 0;
	}

	/* @Override */
	protected string toStringStepPart(TimeRadix radix) {
		return radix.format(tickCount);
	}

	/* @Override */
	public TickStep clone() {
		return new TickStep(threadKey, tickCount);
	}

	/* @Override */
	public Step subtract(Step step) {
		System.Diagnostics.Debug.Assert(isCompatible(step));
		TickStep that = (TickStep) step;
		return new TickStep(this.threadKey, this.tickCount - that.tickCount);
	}

	/* @Override */
	public void execute(PcodeThread<object> emuThread, Stepper stepper, TaskMonitor monitor)
    {
		for (int i = 0; i < tickCount; i++) {
			monitor.incrementProgress(1);
			monitor.checkCancelled();
			stepper.tick(emuThread);
		}
	}
}
